The matrix $C(U)$ is chosen to be the empirical covariance between particles,
\begin{equation}
C(U) = \frac{1}{J} \sum_{k=1}^J (u^{(k)}-\bar{u})(u^{(k)}-\bar u)^{\rm T} \in \mathbb{R}^{d\times d},
\end{equation}
where $\bar u$ denotes the sample mean
\begin{equation}
\bar u = \frac{1}{J}\sum_{j=1}^J u^{(j)}.
\end{equation}

Here we have defined the macroscopic mean and covariance
\begin{equation}
m(\rho) = \int_{\mathbb{R}^d} u \rho(u) \,{\rm d}u, \qquad \mathcal{C}(\rho) = 
\int_{\mathbb{R}^d} (u-m(\rho))(u-m(\rho))^{\rm T} \rho(u)\, {\rm d}u
\end{equation}
and the energy functional
\begin{equation}
E(\rho) = \int_{\mathbb{R}^d} \rho(u) \left(\Psi_R(u) + \ln\rho(u)\right) {\rm d}u.
\end{equation}

We now rewrite (\ref{eq:IPS1}) in the form
\begin{equation} \label{eq:IPS2}
\dot{U} = S(U)\nabla \ln \pi(U) + \sqrt{2S(U)}\dot{\bf W},
\end{equation}
where $S(U) \in \mathbb{R}^{D\times D}$, $D = dJ$, is a block diagonal matrix with $J$ $d\times d$ entries $C(U)$ and ${\bf W}$ denotes
standard $D$-dimensional Brownian motion.

The associated Fokker--Planck equation \cite{sr:P14} 
for the time evolution of the joint density $\mu$ of $U$ can be written as
\begin{equation} \label{eq:FPE0}
\partial_t \mu = \nabla \cdot \left( \mu S \nabla \left\{\ln \mu - \ln \pi \right\} + \mu \nabla \cdot S \right),
\end{equation}
where the vector-valued divergence of the matrix $S$ is defined by
\begin{equation}
(\nabla \cdot S)_i = \sum_{j=1}^D \partial_j S_{ij}, \quad i= 1,\ldots, D.
\end{equation}

 \label{lemma1}
It holds that
\begin{equation}
\nabla \cdot S\,(U) = \frac{d+1}{J}\left(U-\bar U\right) \in \mathbb{R}^D,
\end{equation} 
where $\bar U$ denotes the $D$ dimensional vector consisting of $J$ copies of $\bar u \in \mathbb{R}^d$. In particular, since $\nabla \cdot S \neq 0$, $\pi$ is in general not invariant for the dynamics defined by \eqref{eq:IPS1}.

 We note the properties 
\begin{align}
\nabla_{u^{(j)}} \cdot \left( u^{(j)} (u^{(j)})^{\rm T}\right) &= (d+1) u^{(j)},\\
\nabla_{u^{(j)}} \cdot \left( u^{(j)} (u^{(k)})^{\rm T}\right) &= u^{(k)},\\
\nabla_{u^{(j)}} \cdot \left( u^{(k)} (u^{(j)})^{\rm T}\right) &= d u^{(k)},
\end{align}
$k\not=j$, for the divergence operator. Using
\begin{equation}
C(U) = \frac{1}{J} \sum_{k=1}^M u^{(k)} (u^{(k)})^{\rm T} - \bar u \bar u^{\rm T},
\end{equation}
an explicit calculation reveals then that
\begin{align}
\nabla_{u^{(j)}} \cdot C\,(U) &= 
\frac{d+1}{J} (u^{(j)} - \bar u)  \in \mathbb{R}^d
\end{align}
and hence 
\begin{equation}
\nabla \cdot S \,(U) = \frac{d+1}{J}\left(U-\bar U\right) \in \mathbb{R}^D.
\end{equation}

\begin{align}
\nabla_{u^{(j)}} \cdot \left( u^{(j)} (u^{(j)})^{\rm T}\right) &= (d+1) u^{(j)},\\
\nabla_{u^{(j)}} \cdot \left( u^{(j)} (u^{(k)})^{\rm T}\right) &= u^{(k)},\\
\nabla_{u^{(j)}} \cdot \left( u^{(k)} (u^{(j)})^{\rm T}\right) &= d u^{(k)},
\end{align}

\begin{equation}
C(U) = \frac{1}{J} \sum_{k=1}^M u^{(k)} (u^{(k)})^{\rm T} - \bar u \bar u^{\rm T},
\end{equation}

 Let us consider a one-dimensional Gaussian target measure ($d=1$) with variance $b^2$, i.e. the potential is given by $\Psi_R(u) =  u^2/(2b^2)$. Under the approximating assumptions that the equilibrium density associated to \eqref{eq:IPS1} is a product of $J$ Gaussians with variance $\sigma^2$, and that the covariance at equilibrium can be well-approximated by the state-independent stationary covariance (mean-field assumption),  one can derive the  relation 
\begin{equation}
\sigma^2 \approx \frac{J-2}{J} b^2,
\end{equation}	
which we numerically verified for $J=4$. Note that $\sigma^2 < b^2$, i.e.
the dynamics \eqref{eq:IPS1} systematically underestimates the posterior variance. Since $ \sigma^2 \xrightarrow{J \rightarrow \infty} b^2$, this error vanishes in the large-particle regime, in agreement with the results in \cite{sr:GIHLS19}.

 \label{lemma2}
The Fokker--Planck equation associated to the time evolution of the joint density $\mu$ under the corrected interacting particle 
formulation (\ref{eq:IPS2c})  is of the form
\begin{equation} \label{eq:FPE2}
\partial_t \mu = \nabla \cdot \left( \mu\, S \nabla \left\{ \ln \mu  - \ln \pi \right\} \right)
= \nabla \cdot \left( \mu \,S \nabla \frac{\delta V}{\delta \mu}\right),
\end{equation}
where the energy functional $V$ is the Kullback--Leibler divergence between $\mu$ and $\pi$, given by
\begin{equation}
V(\mu) = \int_{\mathbb{R}^D}  \mu(U) \{\ln \mu (U) - \ln \pi(U) \} \, {\rm d}U.
\end{equation}
